1	import { useEffect, useRef, useState } from 'react';
2	import { buildResultQuery, computeQuizResult } from '../scoring';
3	import type { QuizData, QuizQuestion, QuizResponses } from '../types';
4	
5	export interface QuizStepperProps {
6	  quiz: QuizData;
7	  /**
8	   * Cakemail hosted-form submission URL (the `action` of a Cakemail-rendered
9	   * form). The stepper POSTs `email`, `custom_attributes[firstname]`, and any
10	   * `submissionTags` / level tag as multipart form-data; Cakemail handles list
11	   * add and double opt-in. Quiz scoring happens in the browser, so the redirect
12	   * URL is built locally and the user lands on the results page regardless of
13	   * Cakemail's response.
14	   *
15	   * Optional: provide EITHER `cakemailFormUrl` (built-in best-effort POST) OR
16	   * `onSubmit` (host owns delivery). If both are given, `onSubmit` wins.
17	   */
18	  cakemailFormUrl?: string;
19	  /**
20	   * Override for how the captured contact is delivered. Receives the multipart
21	   * form-data the engine assembled (email, firstname, tags). Use it to route the
22	   * submission through your own endpoint (e.g. a CAPTCHA-gated proxy) instead of
23	   * POSTing straight to Cakemail. Unlike the built-in POST, this hook is
24	   * authoritative: if it throws, the engine shows the thrown message and keeps
25	   * the user on the capture step (no redirect) so they can retry. Resolve to
26	   * proceed to the results page.
27	   */
28	  onSubmit?: (formData: FormData) => Promise<void>;
29	  /**
30	   * Extra content rendered inside the capture form, just above the submit button.
31	   * Use it to mount a pre-submit widget the host needs at submit time (e.g. a
32	   * CAPTCHA whose token your `onSubmit` reads). The engine treats it as opaque.
33	   */
34	  captureExtras?: React.ReactNode;
35	  /**
36	   * Required. Used to build the results redirect path (`/quiz/{slug}/results/?...`).
37	   */
38	  quizSlug: string;
39	  introTitle?: string;
40	  introBody?: string;
41	  startButtonLabel?: string;
42	  submitButtonLabel?: string;
43	  showCorrectness?: boolean;
44	  /**
45	   * Small print shown under the submit button on the capture step. Use it to
46	   * tell the user what they're opting into (e.g. "You'll also receive ...").
47	   */
48	  captureFootnote?: string;
49	  /**
50	   * Tags applied to the contact on submission, sent as Cakemail's
51	   * `tags[<name>]=true` form fields. Use for audience segmentation that the
52	   * email platform's automations can trigger on (e.g. ['aiquiz']).
53	   */
54	  submissionTags?: string[];
55	  /**
56	   * When set, the contact is also tagged with `${levelTagPrefix}${overallLevel}`
57	   * (e.g. prefix 'aiquiz-' + level 'high-risk' => tag 'aiquiz-high-risk'), so a
58	   * nurture sequence can branch on the quiz result tier.
59	   */
60	  levelTagPrefix?: string;
61	}
62	
63	type StepKind = 'intro' | 'question' | 'capture';
64	
65	interface Step {
66	  kind: StepKind;
67	  index: number;
68	}
69	
70	export default function QuizStepper({
71	  quiz,
72	  cakemailFormUrl,
73	  onSubmit,
74	  captureExtras,
75	  quizSlug,
76	  introTitle,
77	  introBody,
78	  startButtonLabel = 'Start the quiz',
79	  submitButtonLabel = 'See my results',
80	  showCorrectness = false,
81	  captureFootnote = "You'll also be subscribed to our list. You can unsubscribe at any time.",
82	  submissionTags,
83	  levelTagPrefix,
84	}: QuizStepperProps) {
85	  // Order questions once on mount. Shuffling lives inside a `useState`
86	  // initializer so each user gets a stable order across re-renders and
87	  // back-button navigation. Section order is always preserved.
88	  const [orderedQuestions] = useState<QuizQuestion[]>(() =>
89	    orderQuestions(quiz),
90	  );
91	  const steps = buildSteps(orderedQuestions);
92	  const [stepIndex, setStepIndex] = useState(0);
93	  const [responses, setResponses] = useState<QuizResponses>({});
94	  const [revealed, setRevealed] = useState<Record<string, boolean>>({});
95	  const [firstName, setFirstName] = useState('');
96	  const [email, setEmail] = useState('');
97	  const [submitting, setSubmitting] = useState(false);
98	  const [submitError, setSubmitError] = useState<string | null>(null);
99	  const initialised = useRef(false);
100	  const startedRef = useRef(false);
101	
102	  useEffect(() => {
103	    if (initialised.current) return;
104	    initialised.current = true;
105	    window.history.replaceState({ quizStep: 0 }, '');
106	
107	    const onPop = (event: PopStateEvent) => {
108	      const next = event.state?.quizStep;
109	      if (typeof next === 'number' && next >= 0 && next < steps.length) {
110	        setStepIndex(next);
111	      }
112	    };
113	    window.addEventListener('popstate', onPop);
114	    return () => window.removeEventListener('popstate', onPop);
115	  }, [steps.length]);
116	
117	  // Fire a generic event whenever the step changes so the host page can react
118	  // (e.g. hide marketing chrome once the quiz is underway). The engine has no
119	  // opinion about what consumers do with this. `quiz:started` is a one-shot
120	  // event the first time the user leaves the intro, intended for analytics.
121	  useEffect(() => {
122	    const step = steps[stepIndex];
123	    window.dispatchEvent(
124	      new CustomEvent('quiz:step-changed', {
125	        detail: { kind: step.kind, index: stepIndex },
126	      }),
127	    );
128	    if (!startedRef.current && step.kind !== 'intro') {
129	      startedRef.current = true;
130	      window.dispatchEvent(new CustomEvent('quiz:started'));
131	    }
132	  }, [stepIndex, steps]);
133	
134	  const goToStep = (next: number) => {
135	    if (next < 0 || next >= steps.length) return;
136	    window.history.pushState({ quizStep: next }, '');
137	    setStepIndex(next);
138	    if (typeof window !== 'undefined') {
139	      window.scrollTo({ top: 0, behavior: 'smooth' });
140	    }
141	  };
142	
143	  // Listen for a `quiz:start-requested` event so a host page can trigger the
144	  // quiz from its own chrome (e.g. a marketing hero "Start the Quiz" button).
145	  // No-op unless currently on the intro step, so duplicate dispatches are safe.
146	  useEffect(() => {
147	    const onStartRequested = () => {
148	      if (steps[stepIndex]?.kind === 'intro') {
149	        goToStep(stepIndex + 1);
150	      }
151	    };
152	    window.addEventListener('quiz:start-requested', onStartRequested);
153	    return () =>
154	      window.removeEventListener('quiz:start-requested', onStartRequested);
155	  }, [stepIndex, steps]);
156	
157	  const step = steps[stepIndex];
158	  const progress = computeProgress(step, steps);
159	
160	  if (step.kind === 'intro') {
161	    return (
162	      <Shell progress={progress} showProgress={false}>
163	        <IntroScreen
164	          title={introTitle ?? quiz.title}
165	          body={introBody ?? quiz.intro}
166	          buttonLabel={startButtonLabel}
167	          onStart={() => goToStep(stepIndex + 1)}
168	        />
169	      </Shell>
170	    );
171	  }
172	
173	  if (step.kind === 'question') {
174	    const question = orderedQuestions[step.index];
175	    const chosenIndex = responses[question.id];
176	    const isRevealed = !!revealed[question.id];
177	
178	    const onPick = (optionIndex: number) => {
179	      setResponses((prev) => ({ ...prev, [question.id]: optionIndex }));
180	      setRevealed((prev) => ({ ...prev, [question.id]: true }));
181	    };
182	
183	    return (
184	      <Shell progress={progress} showProgress>
185	        <QuestionScreen
186	          quiz={quiz}
187	          question={question}
188	          chosenIndex={chosenIndex}
189	          revealed={isRevealed}
190	          showCorrectness={showCorrectness}
191	          onPick={onPick}
192	          onNext={() => goToStep(stepIndex + 1)}
193	        />
194	      </Shell>
195	    );
196	  }
197	
198	  // capture step
199	  const allAnswered = quiz.questions.every((q) => q.id in responses);
200	
201	  const handleSubmit = async (e: React.SyntheticEvent) => {
202	    e.preventDefault();
203	    if (submitting) return;
204	    setSubmitError(null);
205	    setSubmitting(true);
206	
207	    // Score the quiz in the browser so the results URL is ready before the
208	    // Cakemail POST. Doing it client-side also means the user lands on the
209	    // results page even if Cakemail rejects the submission — they finished
210	    // the quiz, they get the result.
211	    const result = computeQuizResult(quiz, responses);
212	    const query = buildResultQuery(result);
213	    const redirectUrl = `/quiz/${quizSlug}/results/?${query.toString()}`;
214	
215	    const formData = new FormData();
216	    formData.append('email', email.trim());
217	    if (firstName.trim()) {
218	      formData.append('custom_attributes[firstname]', firstName.trim());
219	    }
220	    // Cakemail tags use a dict shape: `tags[<name>]=true`. Static tags from the
221	    // host plus an optional result-tier tag drive the nurture sequence.
222	    for (const tag of submissionTags ?? []) {
223	      formData.append(`tags[${tag}]`, 'true');
224	    }
225	    if (levelTagPrefix && result.overallLevel) {
226	      formData.append(`tags[${levelTagPrefix}${result.overallLevel}]`, 'true');
227	    }
228	
229	    // Host-provided delivery wins and is authoritative: if it throws (e.g. a
230	    // CAPTCHA gate rejects the submission), surface the message and keep the user
231	    // on the capture step so they can retry — don't redirect.
232	    if (onSubmit) {
233	      try {
234	        await onSubmit(formData);
235	      } catch (err) {
236	        setSubmitError(
237	          err instanceof Error
238	            ? err.message
239	            : 'Something went wrong. Please try again.',
240	        );
241	        setSubmitting(false);
242	        return;
243	      }
244	    } else if (cakemailFormUrl) {
245	      try {
246	        // `no-cors` fires the POST without requiring Cakemail to send back
247	        // CORS headers. We can't read the response, but for a marketing-form
248	        // submission we don't need to — Cakemail's double opt-in email is the
249	        // user's source of truth, not our success/error state.
250	        await fetch(cakemailFormUrl, {
251	          method: 'POST',
252	          mode: 'no-cors',
253	          body: formData,
254	        });
255	      } catch (err) {
256	        // Network failure only. Log so a real outage shows up in PostHog/console,
257	        // but still send the user to their results — they earned them.
258	        console.error('quiz signup POST failed', err);
259	      }
260	    }
261	
262	    window.location.href = redirectUrl;
263	  };
264	
265	  return (
266	    <Shell progress={progress} showProgress>
267	      <CaptureScreen
268	        firstName={firstName}
269	        email={email}
270	        onFirstNameChange={setFirstName}
271	        onEmailChange={setEmail}
272	        onSubmit={handleSubmit}
273	        submitting={submitting}
274	        canSubmit={allAnswered && email.includes('@')}
275	        submitButtonLabel={submitButtonLabel}
276	        footnote={captureFootnote}
277	        error={submitError}
278	        extras={captureExtras}
279	      />
280	    </Shell>
281	  );
282	}
283	
284	function Shell({
285	  progress,
286	  showProgress,
287	  children,
288	}: {
289	  progress: { current: number; total: number };
290	  showProgress: boolean;
291	  children: React.ReactNode;
292	}) {
293	  const pct = Math.round((progress.current / progress.total) * 100);
294	  return (
295	    <div className="quiz-stepper mx-auto w-full max-w-2xl">
296	      {showProgress ? (
297	        <div className="mb-6">
298	          <div className="mb-1 flex items-center justify-between text-sm text-gray-600">
299	            <span>
300	              Step {progress.current} of {progress.total}
301	            </span>
302	            <span>{pct}%</span>
303	          </div>
304	          <div className="h-2 w-full overflow-hidden rounded-full bg-gray-200">
305	            <div
306	              className="h-full bg-indigo-600 transition-all duration-300"
307	              style={{ width: `${pct}%` }}
308	              role="progressbar"
309	              aria-valuenow={pct}
310	              aria-valuemin={0}
311	              aria-valuemax={100}
312	            />
313	          </div>
314	        </div>
315	      ) : null}
316	      {children}
317	    </div>
318	  );
319	}
