349	function QuestionScreen({
350	  quiz,
351	  question,
352	  chosenIndex,
353	  revealed,
354	  showCorrectness,
355	  onPick,
356	  onNext,
357	}: {
358	  quiz: QuizData;
359	  question: QuizQuestion;
360	  chosenIndex: number | undefined;
361	  revealed: boolean;
362	  showCorrectness: boolean;
363	  onPick: (optionIndex: number) => void;
364	  onNext: () => void;
365	}) {
366	  const section = quiz.sections.find((s) => s.id === question.section);
367	  const maxOptionScore = Math.max(...question.options.map((o) => o.score));
368	  const userGotItRight =
369	    revealed &&
370	    chosenIndex !== undefined &&
371	    question.options[chosenIndex]?.score === maxOptionScore;
372	
373	  return (
374	    <div className="rounded-lg border border-gray-200 bg-white p-6 shadow-sm md:p-8">
375	      {section ? (
376	        <p className="mb-2 text-sm font-medium uppercase tracking-wide text-indigo-600">
377	          {section.label}
378	        </p>
379	      ) : null}
380	      <h2 className="mb-6 text-xl font-semibold text-gray-900 md:text-2xl">{question.text}</h2>
381	      <ul className="space-y-3">
382	        {question.options.map((option, idx) => {
383	          const isChosen = chosenIndex === idx;
384	          const isCorrect = showCorrectness && option.score === maxOptionScore;
385	          const showAsCorrectPick = revealed && isCorrect && userGotItRight;
386	          const showAsCorrectAnswer = revealed && isCorrect && !userGotItRight;
387	          const showAsWrong = revealed && isChosen && !isCorrect;
388	          let optionClasses =
389	            'w-full rounded-md px-4 py-3 text-left transition focus:outline-none focus:ring-2 focus:ring-indigo-500';
390	          if (showAsCorrectPick) {
391	            // User got it right: filled green box on their (correct) pick.
392	            optionClasses += ' border-2 border-green-600 bg-green-50';
393	          } else if (showAsCorrectAnswer) {
394	            // User got it wrong: outline-only on the correct answer so it
395	            // reads as a reference, not a celebration.
396	            optionClasses += ' border-2 border-green-600 bg-white';
397	          } else if (showAsWrong) {
398	            optionClasses += ' border-2 border-orange-500 bg-orange-50';
399	          } else if (isChosen) {
400	            optionClasses += ' border border-indigo-500 bg-indigo-50';
401	          } else if (revealed) {
402	            // Other non-chosen, non-correct options after reveal: mute them.
403	            optionClasses += ' border border-gray-200 bg-white text-gray-500';
404	          } else {
405	            optionClasses += ' border border-gray-300 bg-white hover:border-indigo-400 hover:bg-indigo-50';
406	          }
407	          return (
408	            <li key={idx}>
409	              <button
410	                type="button"
411	                onClick={() => !revealed && onPick(idx)}
412	                disabled={revealed}
413	                className={`${optionClasses} flex items-center justify-between gap-3`}
414	                aria-pressed={isChosen}
415	              >
416	                <span className="text-base">{option.text}</span>
417	                {showAsCorrectPick ? <CorrectIcon /> : showAsWrong ? <WrongIcon /> : null}
418	              </button>
419	            </li>
420	          );
421	        })}
422	      </ul>
423	
424	      {revealed && question.reveal ? (
425	        <div
426	          className="mt-6 rounded-md border-l-4 border-indigo-500 bg-indigo-50 p-4 text-gray-800"
427	          role="status"
428	          aria-live="polite"
429	        >
430	          <p className="whitespace-pre-line">{renderInlineMarkdown(question.reveal)}</p>
431	        </div>
432	      ) : null}
433	
434	      {revealed ? (
435	        <div className="mt-6 flex justify-end">
436	          <button
437	            type="button"
438	            onClick={onNext}
439	            className="rounded-md bg-orange-500 px-5 py-2.5 text-base font-medium text-white shadow-sm transition hover:bg-orange-500/90 focus:outline-none focus:ring-2 focus:ring-orange-500 focus:ring-offset-2"
440	          >
441	            Next
442	          </button>
443	        </div>
444	      ) : null}
445	    </div>
446	  );
447	}
