523	        <button
524	          type="submit"
525	          disabled={!canSubmit || submitting}
526	          className="w-full rounded-md bg-orange-500 px-5 py-3 text-base font-medium text-white shadow-sm transition hover:bg-orange-500/90 focus:outline-none focus:ring-2 focus:ring-orange-500 focus:ring-offset-2 disabled:cursor-not-allowed disabled:bg-gray-400"
527	          data-ph-capture-attribute-quiz-submit="true"
528	        >
529	          {submitting ? 'Submitting…' : submitButtonLabel}
530	        </button>
