538	// Minimal inline markdown: only `[label](url)` links. Kept inline so the
539	// engine has no markdown dependency when extracted.
540	function renderInlineMarkdown(text: string): React.ReactNode[] {
541	  const nodes: React.ReactNode[] = [];
542	  const linkRegex = /\[([^\]]+)\]\(([^)\s]+)\)/g;
543	  let lastIndex = 0;
544	  let match: RegExpExecArray | null;
545	  let key = 0;
546	  while ((match = linkRegex.exec(text)) !== null) {
547	    if (match.index > lastIndex) {
548	      nodes.push(text.slice(lastIndex, match.index));
549	    }
550	    const [, label, url] = match;
551	    const isExternal = /^https?:\/\//i.test(url);
552	    nodes.push(
553	      <a
554	        key={key++}
555	        href={url}
556	        {...(isExternal
557	          ? { target: '_blank', rel: 'noopener noreferrer' }
558	          : {})}
559	        className="text-indigo-700 underline hover:text-indigo-900"
560	      >
561	        {label}
562	      </a>,
563	    );
564	    lastIndex = linkRegex.lastIndex;
565	  }
566	  if (lastIndex < text.length) {
567	    nodes.push(text.slice(lastIndex));
568	  }
569	  return nodes.length > 0 ? nodes : [text];
570	}
571	
572	function buildSteps(questions: QuizQuestion[]): Step[] {
573	  const steps: Step[] = [{ kind: 'intro', index: 0 }];
574	  questions.forEach((_, i) => steps.push({ kind: 'question', index: i }));
575	  steps.push({ kind: 'capture', index: 0 });
576	  return steps;
577	}
578	
579	/**
580	 * Returns the questions in the order they should be presented to the user,
581	 * based on `quiz.randomize`. Section order from the frontmatter is always
582	 * preserved; only the within-section order can be shuffled. Questions that
583	 * belong to no declared section are appended at the end in their original
584	 * order.
585	 */
586	function orderQuestions(quiz: QuizData): QuizQuestion[] {
587	  if (quiz.randomize !== 'within-sections') return quiz.questions;
588	
589	  const bySection = new Map<string, QuizQuestion[]>();
590	  const orphans: QuizQuestion[] = [];
591	  const knownSectionIds = new Set(quiz.sections.map((s) => s.id));
592	  for (const q of quiz.questions) {
593	    if (!knownSectionIds.has(q.section)) {
594	      orphans.push(q);
595	      continue;
596	    }
597	    const bucket = bySection.get(q.section) ?? [];
598	    bucket.push(q);
599	    bySection.set(q.section, bucket);
600	  }
601	
602	  const out: QuizQuestion[] = [];
603	  for (const section of quiz.sections) {
604	    const bucket = bySection.get(section.id);
605	    if (!bucket) continue;
606	    out.push(...shuffle(bucket));
607	  }
608	  out.push(...orphans);
609	  return out;
610	}
611	
612	function shuffle<T>(items: T[]): T[] {
613	  const out = items.slice();
614	  for (let i = out.length - 1; i > 0; i--) {
615	    const j = Math.floor(Math.random() * (i + 1));
616	    [out[i], out[j]] = [out[j], out[i]];
617	  }
618	  return out;
619	}
620	
621	function computeProgress(step: Step, steps: Step[]): { current: number; total: number } {
622	  const questionSteps = steps.filter((s) => s.kind === 'question').length;
623	  if (step.kind === 'intro') return { current: 0, total: questionSteps };
624	  if (step.kind === 'capture') return { current: questionSteps, total: questionSteps };
625	  return { current: step.index + 1, total: questionSteps };
626	}
