633	      fill="currentColor"
634	      aria-label="Correct"
635	      role="img"
636	    >
637	      <path
638	        fillRule="evenodd"
639	        clipRule="evenodd"
640	        d="M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16zm3.857-9.809a.75.75 0 0 0-1.214-.882l-3.483 4.79-1.88-1.88a.75.75 0 1 0-1.06 1.061l2.5 2.5a.75.75 0 0 0 1.137-.089l4-5.5z"
641	      />
642	    </svg>
