import { useEffect, useRef, useState } from 'react';
import { buildResultQuery, computeQuizResult } from '../scoring';
import type { QuizData, QuizQuestion, QuizResponses } from '../types';

export interface QuizStepperProps {
  quiz: QuizData;
  /**
   * Cakemail hosted-form submission URL (the `action` of a Cakemail-rendered
   * form). The stepper POSTs `email`, `custom_attributes[firstname]`, and any
   * `submissionTags` / level tag as multipart form-data; Cakemail handles list
   * add and double opt-in. Quiz scoring happens in the browser, so the redirect
   * URL is built locally and the user lands on the results page regardless of
   * Cakemail's response.
   *
   * Optional: provide EITHER `cakemailFormUrl` (built-in best-effort POST) OR
   * `onSubmit` (host owns delivery). If both are given, `onSubmit` wins.
   */
  cakemailFormUrl?: string;
  /**
   * Override for how the captured contact is delivered. Receives the multipart
   * form-data the engine assembled (email, firstname, tags). Use it to route the
   * submission through your own endpoint (e.g. a CAPTCHA-gated proxy) instead of
   * POSTing straight to Cakemail. Unlike the built-in POST, this hook is
   * authoritative: if it throws, the engine shows the thrown message and keeps
   * the user on the capture step (no redirect) so they can retry. Resolve to
   * proceed to the results page.
   */
  onSubmit?: (formData: FormData) => Promise<void>;
  /**
   * Extra content rendered inside the capture form, just above the submit button.
   * Use it to mount a pre-submit widget the host needs at submit time (e.g. a
   * CAPTCHA whose token your `onSubmit` reads). The engine treats it as opaque.
   */
  captureExtras?: React.ReactNode;
  /**
   * Required. Used to build the results redirect path (`/quiz/{slug}/results/?...`).
   */
  quizSlug: string;
  introTitle?: string;
  introBody?: string;
  startButtonLabel?: string;
  submitButtonLabel?: string;
  showCorrectness?: boolean;
  /**
   * Small print shown under the submit button on the capture step. Use it to
   * tell the user what they're opting into (e.g. "You'll also receive ...").
   */
  captureFootnote?: string;
  /**
   * Tags applied to the contact on submission, sent as Cakemail's
   * `tags[<name>]=true` form fields. Use for audience segmentation that the
   * email platform's automations can trigger on (e.g. ['aiquiz']).
   */
  submissionTags?: string[];
  /**
   * When set, the contact is also tagged with `${levelTagPrefix}${overallLevel}`
   * (e.g. prefix 'aiquiz-' + level 'high-risk' => tag 'aiquiz-high-risk'), so a
   * nurture sequence can branch on the quiz result tier.
   */
  levelTagPrefix?: string;
}

type StepKind = 'intro' | 'question' | 'capture';

interface Step {
  kind: StepKind;
  index: number;
}

export default function QuizStepper({
  quiz,
  cakemailFormUrl,
  onSubmit,
  captureExtras,
  quizSlug,
  introTitle,
  introBody,
  startButtonLabel = 'Start the quiz',
  submitButtonLabel = 'See my results',
  showCorrectness = false,
  captureFootnote = "You'll also be subscribed to our list. You can unsubscribe at any time.",
  submissionTags,
  levelTagPrefix,
}: QuizStepperProps) {
  // Order questions once on mount. Shuffling lives inside a `useState`
  // initializer so each user gets a stable order across re-renders and
  // back-button navigation. Section order is always preserved.
  const [orderedQuestions] = useState<QuizQuestion[]>(() =>
    orderQuestions(quiz),
  );
  const steps = buildSteps(orderedQuestions);
  const [stepIndex, setStepIndex] = useState(0);
  const [responses, setResponses] = useState<QuizResponses>({});
  const [revealed, setRevealed] = useState<Record<string, boolean>>({});
  const [firstName, setFirstName] = useState('');
  const [email, setEmail] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const initialised = useRef(false);
  const startedRef = useRef(false);

  useEffect(() => {
    if (initialised.current) return;
    initialised.current = true;
    window.history.replaceState({ quizStep: 0 }, '');

    const onPop = (event: PopStateEvent) => {
      const next = event.state?.quizStep;
      if (typeof next === 'number' && next >= 0 && next < steps.length) {
        setStepIndex(next);
      }
    };
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, [steps.length]);

  // Fire a generic event whenever the step changes so the host page can react
  // (e.g. hide marketing chrome once the quiz is underway). The engine has no
  // opinion about what consumers do with this. `quiz:started` is a one-shot
  // event the first time the user leaves the intro, intended for analytics.
  useEffect(() => {
    const step = steps[stepIndex];
    window.dispatchEvent(
      new CustomEvent('quiz:step-changed', {
        detail: { kind: step.kind, index: stepIndex },
      }),
    );
    if (!startedRef.current && step.kind !== 'intro') {
      startedRef.current = true;
      window.dispatchEvent(new CustomEvent('quiz:started'));
    }
  }, [stepIndex, steps]);

  const goToStep = (next: number) => {
    if (next < 0 || next >= steps.length) return;
    window.history.pushState({ quizStep: next }, '');
    setStepIndex(next);
    if (typeof window !== 'undefined') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  // Listen for a `quiz:start-requested` event so a host page can trigger the
  // quiz from its own chrome (e.g. a marketing hero "Start the Quiz" button).
  // No-op unless currently on the intro step, so duplicate dispatches are safe.
  useEffect(() => {
    const onStartRequested = () => {
      if (steps[stepIndex]?.kind === 'intro') {
        goToStep(stepIndex + 1);
      }
    };
    window.addEventListener('quiz:start-requested', onStartRequested);
    return () =>
      window.removeEventListener('quiz:start-requested', onStartRequested);
  }, [stepIndex, steps]);

  const step = steps[stepIndex];
  const progress = computeProgress(step, steps);

  if (step.kind === 'intro') {
    return (
      <Shell progress={progress} showProgress={false}>
        <IntroScreen
          title={introTitle ?? quiz.title}
          body={introBody ?? quiz.intro}
          buttonLabel={startButtonLabel}
          onStart={() => goToStep(stepIndex + 1)}
        />
      </Shell>
    );
  }

  if (step.kind === 'question') {
    const question = orderedQuestions[step.index];
    const chosenIndex = responses[question.id];
    const isRevealed = !!revealed[question.id];

    const onPick = (optionIndex: number) => {
      setResponses((prev) => ({ ...prev, [question.id]: optionIndex }));
      setRevealed((prev) => ({ ...prev, [question.id]: true }));
    };

    return (
      <Shell progress={progress} showProgress>
        <QuestionScreen
          quiz={quiz}
          question={question}
          chosenIndex={chosenIndex}
          revealed={isRevealed}
          showCorrectness={showCorrectness}
          onPick={onPick}
          onNext={() => goToStep(stepIndex + 1)}
        />
      </Shell>
    );
  }

  // capture step
  const allAnswered = quiz.questions.every((q) => q.id in responses);

  const handleSubmit = async (e: React.SyntheticEvent) => {
    e.preventDefault();
    if (submitting) return;
    setSubmitError(null);
    setSubmitting(true);

    // Score the quiz in the browser so the results URL is ready before the
    // Cakemail POST. Doing it client-side also means the user lands on the
    // results page even if Cakemail rejects the submission — they finished
    // the quiz, they get the result.
    const result = computeQuizResult(quiz, responses);
    const query = buildResultQuery(result);
    const redirectUrl = `/quiz/${quizSlug}/results/?${query.toString()}`;

    const formData = new FormData();
    formData.append('email', email.trim());
    if (firstName.trim()) {
      formData.append('custom_attributes[firstname]', firstName.trim());
    }
    // Cakemail tags use a dict shape: `tags[<name>]=true`. Static tags from the
    // host plus an optional result-tier tag drive the nurture sequence.
    for (const tag of submissionTags ?? []) {
      formData.append(`tags[${tag}]`, 'true');
    }
    if (levelTagPrefix && result.overallLevel) {
      formData.append(`tags[${levelTagPrefix}${result.overallLevel}]`, 'true');
    }

    // Host-provided delivery wins and is authoritative: if it throws (e.g. a
    // CAPTCHA gate rejects the submission), surface the message and keep the user
    // on the capture step so they can retry — don't redirect.
    if (onSubmit) {
      try {
        await onSubmit(formData);
      } catch (err) {
        setSubmitError(
          err instanceof Error
            ? err.message
            : 'Something went wrong. Please try again.',
        );
        setSubmitting(false);
        return;
      }
    } else if (cakemailFormUrl) {
      try {
        // `no-cors` fires the POST without requiring Cakemail to send back
        // CORS headers. We can't read the response, but for a marketing-form
        // submission we don't need to — Cakemail's double opt-in email is the
        // user's source of truth, not our success/error state.
        await fetch(cakemailFormUrl, {
          method: 'POST',
          mode: 'no-cors',
          body: formData,
        });
      } catch (err) {
        // Network failure only. Log so a real outage shows up in PostHog/console,
        // but still send the user to their results — they earned them.
        console.error('quiz signup POST failed', err);
      }
    }

    window.location.href = redirectUrl;
  };

  return (
    <Shell progress={progress} showProgress>
      <CaptureScreen
        firstName={firstName}
        email={email}
        onFirstNameChange={setFirstName}
        onEmailChange={setEmail}
        onSubmit={handleSubmit}
        submitting={submitting}
        canSubmit={allAnswered && email.includes('@')}
        submitButtonLabel={submitButtonLabel}
        footnote={captureFootnote}
        error={submitError}
        extras={captureExtras}
      />
    </Shell>
  );
}

function Shell({
  progress,
  showProgress,
  children,
}: {
  progress: { current: number; total: number };
  showProgress: boolean;
  children: React.ReactNode;
}) {
  const pct = Math.round((progress.current / progress.total) * 100);
  return (
    <div className="quiz-stepper mx-auto w-full max-w-2xl">
      {showProgress ? (
        <div className="mb-6">
          <div className="mb-1 flex items-center justify-between text-sm text-gray-600">
            <span>
              Step {progress.current} of {progress.total}
            </span>
            <span>{pct}%</span>
          </div>
          <div className="h-2 w-full overflow-hidden rounded-full bg-gray-200">
            <div
              className="h-full bg-indigo-600 transition-all duration-300"
              style={{ width: `${pct}%` }}
              role="progressbar"
              aria-valuenow={pct}
              aria-valuemin={0}
              aria-valuemax={100}
            />
          </div>
        </div>
      ) : null}
      {children}
    </div>
  );
}

function IntroScreen({
  title,
  body,
  buttonLabel,
  onStart,
}: {
  title?: string;
  body?: string;
  buttonLabel: string;
  onStart: () => void;
}) {
  return (
    <div className="rounded-lg border border-gray-200 bg-white p-6 text-center shadow-sm md:p-8">
      {title ? <h2 className="mb-4 text-2xl font-semibold text-gray-900">{title}</h2> : null}
      {body ? (
        <p className="mb-6 whitespace-pre-line text-base text-gray-700 md:text-lg">{body}</p>
      ) : null}
      <button
        type="button"
        onClick={onStart}
        className="rounded-md bg-orange-500 px-6 py-3 text-base font-medium text-white shadow-sm transition hover:bg-orange-500/90 focus:outline-none focus:ring-2 focus:ring-orange-500 focus:ring-offset-2"
      >
        {buttonLabel}
      </button>
    </div>
  );
}

function QuestionScreen({
  quiz,
  question,
  chosenIndex,
  revealed,
  showCorrectness,
  onPick,
  onNext,
}: {
  quiz: QuizData;
  question: QuizQuestion;
  chosenIndex: number | undefined;
  revealed: boolean;
  showCorrectness: boolean;
  onPick: (optionIndex: number) => void;
  onNext: () => void;
}) {
  const section = quiz.sections.find((s) => s.id === question.section);
  const maxOptionScore = Math.max(...question.options.map((o) => o.score));
  const userGotItRight =
    revealed &&
    chosenIndex !== undefined &&
    question.options[chosenIndex]?.score === maxOptionScore;

  return (
    <div className="rounded-lg border border-gray-200 bg-white p-6 shadow-sm md:p-8">
      {section ? (
        <p className="mb-2 text-sm font-medium uppercase tracking-wide text-indigo-600">
          {section.label}
        </p>
      ) : null}
      <h2 className="mb-6 text-xl font-semibold text-gray-900 md:text-2xl">{question.text}</h2>
      <ul className="space-y-3">
        {question.options.map((option, idx) => {
          const isChosen = chosenIndex === idx;
          const isCorrect = showCorrectness && option.score === maxOptionScore;
          const showAsCorrectPick = revealed && isCorrect && userGotItRight;
          const showAsCorrectAnswer = revealed && isCorrect && !userGotItRight;
          const showAsWrong = revealed && isChosen && !isCorrect;
          let optionClasses =
            'w-full rounded-md px-4 py-3 text-left transition focus:outline-none focus:ring-2 focus:ring-indigo-500';
          if (showAsCorrectPick) {
            // User got it right: filled green box on their (correct) pick.
            optionClasses += ' border-2 border-green-600 bg-green-50';
          } else if (showAsCorrectAnswer) {
            // User got it wrong: outline-only on the correct answer so it
            // reads as a reference, not a celebration.
            optionClasses += ' border-2 border-green-600 bg-white';
          } else if (showAsWrong) {
            optionClasses += ' border-2 border-orange-500 bg-orange-50';
          } else if (isChosen) {
            optionClasses += ' border border-indigo-500 bg-indigo-50';
          } else if (revealed) {
            // Other non-chosen, non-correct options after reveal: mute them.
            optionClasses += ' border border-gray-200 bg-white text-gray-500';
          } else {
            optionClasses += ' border border-gray-300 bg-white hover:border-indigo-400 hover:bg-indigo-50';
          }
          return (
            <li key={idx}>
              <button
                type="button"
                onClick={() => !revealed && onPick(idx)}
                disabled={revealed}
                className={`${optionClasses} flex items-center justify-between gap-3`}
                aria-pressed={isChosen}
              >
                <span className="text-base">{option.text}</span>
                {showAsCorrectPick ? <CorrectIcon /> : showAsWrong ? <WrongIcon /> : null}
              </button>
            </li>
          );
        })}
      </ul>

      {revealed && question.reveal ? (
        <div
          className="mt-6 rounded-md border-l-4 border-indigo-500 bg-indigo-50 p-4 text-gray-800"
          role="status"
          aria-live="polite"
        >
          <p className="whitespace-pre-line">{renderInlineMarkdown(question.reveal)}</p>
        </div>
      ) : null}

      {revealed ? (
        <div className="mt-6 flex justify-end">
          <button
            type="button"
            onClick={onNext}
            className="rounded-md bg-orange-500 px-5 py-2.5 text-base font-medium text-white shadow-sm transition hover:bg-orange-500/90 focus:outline-none focus:ring-2 focus:ring-orange-500 focus:ring-offset-2"
          >
            Next
          </button>
        </div>
      ) : null}
    </div>
  );
}

function CaptureScreen({
  firstName,
  email,
  onFirstNameChange,
  onEmailChange,
  onSubmit,
  submitting,
  canSubmit,
  submitButtonLabel,
  footnote,
  error,
  extras,
}: {
  firstName: string;
  email: string;
  onFirstNameChange: (v: string) => void;
  onEmailChange: (v: string) => void;
  onSubmit: (e: React.SyntheticEvent) => void;
  submitting: boolean;
  canSubmit: boolean;
  submitButtonLabel: string;
  footnote: string;
  error: string | null;
  extras?: React.ReactNode;
}) {
  return (
    <form
      onSubmit={onSubmit}
      className="rounded-lg border border-gray-200 bg-white p-6 shadow-sm md:p-8"
      noValidate
    >
      <h2 className="mb-2 text-2xl font-semibold text-gray-900">Where should we send your results?</h2>
      <p className="mb-6 text-gray-700">
        Enter your email and we'll show you your score and what it means.
      </p>
      <div className="space-y-4">
        <div>
          <label htmlFor="quiz-first-name" className="mb-1 block text-sm font-medium text-gray-700">
            First name
          </label>
          <input
            id="quiz-first-name"
            type="text"
            autoComplete="given-name"
            value={firstName}
            onChange={(e) => onFirstNameChange(e.target.value)}
            className="w-full rounded-md border border-gray-300 px-3 py-2 text-base shadow-sm focus:border-orange-500 focus:outline-none focus:ring-1 focus:ring-orange-500"
          />
        </div>
        <div>
          <label htmlFor="quiz-email" className="mb-1 block text-sm font-medium text-gray-700">
            Email <span className="text-red-600">*</span>
          </label>
          <input
            id="quiz-email"
            type="email"
            autoComplete="email"
            required
            value={email}
            onChange={(e) => onEmailChange(e.target.value)}
            className="w-full rounded-md border border-gray-300 px-3 py-2 text-base shadow-sm focus:border-orange-500 focus:outline-none focus:ring-1 focus:ring-orange-500"
          />
        </div>
      </div>

      {extras ? <div className="mt-4">{extras}</div> : null}

      {error ? (
        <p className="mt-4 text-sm text-red-600" role="alert">
          {error}
        </p>
      ) : null}

      <div className="mt-6">
        <button
          type="submit"
          disabled={!canSubmit || submitting}
          className="w-full rounded-md bg-orange-500 px-5 py-3 text-base font-medium text-white shadow-sm transition hover:bg-orange-500/90 focus:outline-none focus:ring-2 focus:ring-orange-500 focus:ring-offset-2 disabled:cursor-not-allowed disabled:bg-gray-400"
          data-ph-capture-attribute-quiz-submit="true"
        >
          {submitting ? 'Submitting…' : submitButtonLabel}
        </button>
      </div>

      <p className="mt-4 text-xs text-gray-500">{footnote}</p>
    </form>
  );
}

// Minimal inline markdown: only `[label](url)` links. Kept inline so the
// engine has no markdown dependency when extracted.
function renderInlineMarkdown(text: string): React.ReactNode[] {
  const nodes: React.ReactNode[] = [];
  const linkRegex = /\[([^\]]+)\]\(([^)\s]+)\)/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;
  let key = 0;
  while ((match = linkRegex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      nodes.push(text.slice(lastIndex, match.index));
    }
    const [, label, url] = match;
    const isExternal = /^https?:\/\//i.test(url);
    nodes.push(
      <a
        key={key++}
        href={url}
        {...(isExternal
          ? { target: '_blank', rel: 'noopener noreferrer' }
          : {})}
        className="text-indigo-700 underline hover:text-indigo-900"
      >
        {label}
      </a>,
    );
    lastIndex = linkRegex.lastIndex;
  }
  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }
  return nodes.length > 0 ? nodes : [text];
}

function buildSteps(questions: QuizQuestion[]): Step[] {
  const steps: Step[] = [{ kind: 'intro', index: 0 }];
  questions.forEach((_, i) => steps.push({ kind: 'question', index: i }));
  steps.push({ kind: 'capture', index: 0 });
  return steps;
}

/**
 * Returns the questions in the order they should be presented to the user,
 * based on `quiz.randomize`. Section order from the frontmatter is always
 * preserved; only the within-section order can be shuffled. Questions that
 * belong to no declared section are appended at the end in their original
 * order.
 */
function orderQuestions(quiz: QuizData): QuizQuestion[] {
  if (quiz.randomize !== 'within-sections') return quiz.questions;

  const bySection = new Map<string, QuizQuestion[]>();
  const orphans: QuizQuestion[] = [];
  const knownSectionIds = new Set(quiz.sections.map((s) => s.id));
  for (const q of quiz.questions) {
    if (!knownSectionIds.has(q.section)) {
      orphans.push(q);
      continue;
    }
    const bucket = bySection.get(q.section) ?? [];
    bucket.push(q);
    bySection.set(q.section, bucket);
  }

  const out: QuizQuestion[] = [];
  for (const section of quiz.sections) {
    const bucket = bySection.get(section.id);
    if (!bucket) continue;
    out.push(...shuffle(bucket));
  }
  out.push(...orphans);
  return out;
}

function shuffle<T>(items: T[]): T[] {
  const out = items.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

function computeProgress(step: Step, steps: Step[]): { current: number; total: number } {
  const questionSteps = steps.filter((s) => s.kind === 'question').length;
  if (step.kind === 'intro') return { current: 0, total: questionSteps };
  if (step.kind === 'capture') return { current: questionSteps, total: questionSteps };
  return { current: step.index + 1, total: questionSteps };
}

function CorrectIcon() {
  return (
    <svg
      className="h-6 w-6 shrink-0 text-green-600"
      viewBox="0 0 20 20"
      fill="currentColor"
      aria-label="Correct"
      role="img"
    >
      <path
        fillRule="evenodd"
        clipRule="evenodd"
        d="M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16zm3.857-9.809a.75.75 0 0 0-1.214-.882l-3.483 4.79-1.88-1.88a.75.75 0 1 0-1.06 1.061l2.5 2.5a.75.75 0 0 0 1.137-.089l4-5.5z"
      />
    </svg>
  );
}

function WrongIcon() {
  return (
    <svg
      className="h-6 w-6 shrink-0 text-red-600"
      viewBox="0 0 20 20"
      fill="currentColor"
      aria-label="Incorrect"
      role="img"
    >
      <path
        fillRule="evenodd"
        clipRule="evenodd"
        d="M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16zM8.28 7.22a.75.75 0 0 0-1.06 1.06L8.94 10l-1.72 1.72a.75.75 0 1 0 1.06 1.06L10 11.06l1.72 1.72a.75.75 0 1 0 1.06-1.06L11.06 10l1.72-1.72a.75.75 0 0 0-1.06-1.06L10 8.94 8.28 7.22z"
      />
    </svg>
  );
}

