/**
 * Wraps a per-section, per-level result block in a quiz MDX file.
 *
 * Renders only when the current results URL has `?{section}={level}` in its
 * query string. The results page is responsible for building that URL from
 * computed scores, typically via `buildResultQuery(result)` from the engine.
 *
 *   <ResultCard section="code-quality" level="high-risk" image={icon}>
 *     ...markdown content...
 *   </ResultCard>
 *
 * `image` is optional. Pass an imported `ImageMetadata` (preferred, so Astro
 * can optimise it) or a plain URL string to show a small icon atop the card.
 */
import { Image } from 'astro:assets';
import type { ImageMetadata } from 'astro';

interface Props {
  section: string;
  level: string;
  image?: ImageMetadata | string;
}

const { section, level, image } = Astro.props;
const requestedLevel = Astro.url.searchParams.get(section);
const shouldRender = requestedLevel === level;
---

{
  shouldRender && (
    <section
      class="quiz-result-card mb-8 rounded-lg border border-gray-200 bg-white p-6 shadow-sm md:p-8"
      data-section={section}
      data-level={level}
    >
      {image &&
        (typeof image === 'string' ? (
          <img src={image} alt="" class="mb-4 h-20 w-20 object-contain" loading="lazy" />
        ) : (
          <Image src={image} alt="" class="mb-4 h-20 w-20 object-contain" loading="lazy" />
        ))}
      <slot />
    </section>
  )
}

