import { useRef, useState } from 'react';
import QuizStepper, {
  type QuizStepperProps,
} from '@/lib/quiz-engine/components/QuizStepper';
import Turnstile, { type TurnstileHandle } from '@/components/global/turnstile';

/**
 * APR-specific wrapper around the (APR-agnostic) quiz engine that gates the
 * capture submission behind Cloudflare Turnstile.
 *
 * It supplies the engine's two generic hooks:
 *   - `captureExtras` — mounts the Turnstile widget inside the capture form.
 *   - `onSubmit` — appends the token and POSTs to `/api/newsletter-signup`
 *     (same-origin), which verifies the challenge and forwards to Cakemail
 *     server-side, exactly like the newsletter / AI forms. Throwing keeps the
 *     user on the capture step with a message; resolving lets the engine
 *     redirect to results.
 *
 * The engine itself stays free of Turnstile / endpoint knowledge so it remains
 * extractable as a standalone package.
 */
type GatedQuizStepperProps = Omit<
  QuizStepperProps,
  'cakemailFormUrl' | 'onSubmit' | 'captureExtras'
>;

export default function GatedQuizStepper(props: GatedQuizStepperProps) {
  const [token, setToken] = useState('');
  const turnstileRef = useRef<TurnstileHandle>(null);

  const handleSubmit = async (formData: FormData) => {
    if (!token) {
      throw new Error(
        'Please wait a moment for the verification to finish, then try again.',
      );
    }

    formData.append('form', 'quiz');
    formData.append('cf-turnstile-response', token);

    let response: Response;
    try {
      response = await fetch('/api/newsletter-signup', {
        method: 'POST',
        body: formData,
      });
    } catch (err) {
      console.error('quiz signup POST failed', err);
      setToken('');
      turnstileRef.current?.reset();
      throw new Error('Something went wrong. Please try again.');
    }

    if (!response.ok) {
      setToken('');
      turnstileRef.current?.reset();
      throw new Error('We couldn’t verify your submission. Please try again.');
    }
  };

  return (
    <QuizStepper
      {...props}
      onSubmit={handleSubmit}
      captureExtras={
        <Turnstile
          ref={turnstileRef}
          onToken={setToken}
          onExpire={() => setToken('')}
        />
      }
    />
  );
}

