import Layout from '@/layouts/base.astro';
import GatedQuizStepper from '@/components/quiz/GatedQuizStepper';
import Logo from '@/assets/images/global/APR-Logo-2020_Horizontal_RGB.svg';
import { Image } from 'astro:assets';
import { getCollection, getEntry } from 'astro:content';

export async function getStaticPaths() {
  const quizzes = await getCollection('quizzes');
  return quizzes.map((quiz) => ({ params: { slug: quiz.id } }));
}

const { slug } = Astro.params;
const entry = await getEntry('quizzes', slug!);
if (!entry) {
  return new Response(null, { status: 404, statusText: 'Not found' });
}

const data = entry.data;
const persuasionParagraphs = data.persuasion
  ? data.persuasion
      .split(/\n\s*\n/)
      .map((p: string) => p.trim())
      .filter(Boolean)
  : [];
---

<Layout
  title={data.title}
  description={data.description ?? data.title}
  includeCoursesCTA={false}
  hideChrome={true}
>
  <header class="border-b border-gray-200 bg-white">
    <div class="container mx-auto flex items-center px-4 py-3">
      <a href="/" aria-label="Agile Pain Relief home">
        <img
          src={Logo.src}
          alt="Agile Pain Relief"
          class="xs:h-12 h-10 w-auto"
        />
      </a>
    </div>
  </header>

  <div class="container mx-auto px-4 py-8 md:py-12">
    <div data-quiz-chrome>
      {
        data.heroHeading || data.heroBody ? (
          <section class="mx-auto mb-12 max-w-3xl text-center">
            {data.heroHeading ? (
              <h1 class="mb-4 text-3xl font-bold text-gray-900 md:text-5xl">
                {data.heroHeading}
              </h1>
            ) : (
              <h1 class="mb-4 text-3xl font-bold text-gray-900 md:text-5xl">
                {data.title}
              </h1>
            )}
            {data.heroBody ? (
              <p class="text-lg leading-relaxed text-gray-700 md:text-xl">
                {data.heroBody}
              </p>
            ) : null}
            <div class="mt-8">
              <button
                type="button"
                data-quiz-start
                class="inline-block rounded-md bg-orange-500 px-6 py-3 text-base font-medium text-white shadow-sm transition hover:bg-orange-500/90 focus:ring-2 focus:ring-orange-500 focus:ring-offset-2 focus:outline-none"
              >
                Test Your Knowledge
              </button>
            </div>
          </section>
        ) : null
      }

      {
        data.sections.length > 0 ? (
          <section class="mx-auto mb-12 max-w-3xl">
            {data.categoriesHeading ? (
              <h2 class="mb-6 text-center text-2xl font-semibold text-gray-900 md:text-3xl">
                {data.categoriesHeading}
              </h2>
            ) : null}
            <div class="grid grid-cols-1 gap-5 md:grid-cols-2">
              {data.sections.map((section) => (
                <div class="flex flex-col rounded-lg border border-gray-200 bg-white p-6 shadow-sm">
                  {section.image ? (
                    typeof section.image === 'string' ? (
                      <img
                        src={section.image}
                        alt=""
                        class="mb-4 h-32 w-full rounded-md object-contain"
                        loading="lazy"
                      />
                    ) : (
                      <Image
                        src={section.image}
                        alt=""
                        class="mb-4 h-32 w-full rounded-md object-contain"
                        loading="lazy"
                      />
                    )
                  ) : null}
                  <h3 class="mb-2 text-xl font-semibold text-gray-900">
                    {section.label}
                  </h3>
                  {section.blurb ? (
                    <p class="text-base leading-relaxed text-gray-700">
                      {section.blurb}
                    </p>
                  ) : null}
                </div>
              ))}
            </div>
          </section>
        ) : null
      }

      {
        persuasionParagraphs.length > 0 ? (
          <section class="mx-auto mb-12 max-w-3xl rounded-lg border border-indigo-200 bg-indigo-50 p-6 md:p-8">
            {persuasionParagraphs.map((paragraph) => (
              <p class="mb-4 text-base leading-relaxed text-gray-800 last:mb-0 md:text-lg">
                {paragraph}
              </p>
            ))}
            <ul class="mt-6 grid grid-cols-1 gap-3 text-base text-gray-800 sm:grid-cols-2">
              <li class="flex items-start gap-2">
                <span
                  aria-hidden="true"
                  class="mt-0.5 font-bold text-green-600"
                >
                  ✓
                </span>
                <span>Free</span>
              </li>
              <li class="flex items-start gap-2">
                <span
                  aria-hidden="true"
                  class="mt-0.5 font-bold text-green-600"
                >
                  ✓
                </span>
                <span>Twelve questions</span>
              </li>
              <li class="flex items-start gap-2">
                <span
                  aria-hidden="true"
                  class="mt-0.5 font-bold text-green-600"
                >
                  ✓
                </span>
                <span>Real studies, real citations</span>
              </li>
              <li class="flex items-start gap-2">
                <span
                  aria-hidden="true"
                  class="mt-0.5 font-bold text-green-600"
                >
                  ✓
                </span>
                <span>Immediate Results </span>
              </li>
              <li class="flex items-start gap-2">
                <span
                  aria-hidden="true"
                  class="mt-0.5 font-bold text-green-600"
                >
                  ✓
                </span>
                <span>
                  <b>Deep dive</b> on the failure modes
                </span>
              </li>
              <li class="flex items-start gap-2">
                <span
                  aria-hidden="true"
                  class="mt-0.5 font-bold text-green-600"
                >
                  ✓
                </span>
                <span>
                  Follow-up series on dealing with these problems on your team
                </span>
              </li>
            </ul>
          </section>
        ) : null
      }
    </div>

    <section id="quiz" class="mx-auto max-w-2xl scroll-mt-24">
      <GatedQuizStepper
        client:load
        quiz={data}
        submissionTags={data.submissionTags}
        levelTagPrefix={data.levelTagPrefix}
        quizSlug={entry.id}
        introTitle=""
        startButtonLabel="Test Your Knowledge"
        showCorrectness
        captureFootnote="You'll also receive a deep dive on these failure modes and a short series of follow-up emails on how to deal with them in your team. You can unsubscribe at any time."
      />
    </section>
  </div>
</Layout>

<script>
  // Hide the marketing chrome (hero, category cards, persuasion block) once
  // the user starts the quiz. The stepper fires `quiz:step-changed` on every
  // step transition, including back-navigation to intro, so the chrome
  // re-appears if the user returns to the intro screen.
  const chrome = document.querySelector<HTMLElement>('[data-quiz-chrome]');
  if (chrome) {
    window.addEventListener('quiz:step-changed', (event) => {
      const detail = (event as CustomEvent<{ kind: string }>).detail;
      chrome.style.display = detail?.kind === 'intro' ? '' : 'none';
    });
  }

  // The hero "Test Your Knowledge" button advances the stepper past its intro step.
  // Without this, the marketing chrome's CTA was redundant with the stepper's
  // own intro screen and offered no obvious affordance to begin.
  document.querySelectorAll<HTMLButtonElement>('[data-quiz-start]').forEach(
    (button) => {
      button.addEventListener('click', () => {
        window.dispatchEvent(new CustomEvent('quiz:start-requested'));
      });
    },
  );
</script>

<script is:inline define:vars={{ quizSlug: entry.id }}>
  window.addEventListener('quiz:started', () => {
    if (typeof posthog !== 'undefined') {
      posthog.capture('quiz_started', { quiz: quizSlug });
    }
  });
</script>

