---
export const prerender = false;

import Layout from '@/layouts/base.astro';
import { findLevel } from '@/lib/quiz-engine';
import { getEntry, render } from 'astro:content';

const { slug } = Astro.params;
const entry = await getEntry('quizzes', slug!);
if (!entry) {
  return new Response(null, { status: 404, statusText: 'Not found' });
}

const data = entry.data;
const params = Astro.url.searchParams;
const totalRaw = params.get('total');
const maxRaw = params.get('max');
const level = params.get('level');

const total = totalRaw !== null ? parseInt(totalRaw, 10) : NaN;
const maxTotal = maxRaw !== null ? parseInt(maxRaw, 10) : NaN;

// If essential params are missing, send the user back to the quiz rather
// than showing a broken results page.
if (Number.isNaN(total) || Number.isNaN(maxTotal) || !level) {
  return Astro.redirect(`/quiz/${entry.id}/`);
}

const overall = findLevel(total, data.overallLevels);
const overallTitle = overall?.title ?? overall?.level ?? 'Your result';

const { Content } = await render(entry);
---

<Layout
  title={`${data.title} — Results`}
  description={data.description ?? data.title}
  includeCoursesCTA={false}
  noIndex={true}
>
  <div class="container mx-auto px-4 py-12 md:py-16">
    <section class="mx-auto mb-10 max-w-3xl text-center">
      <p class="mb-2 text-sm font-medium uppercase tracking-wide text-indigo-600">Your result</p>
      <h1 class="mb-4 text-3xl font-bold text-gray-900 md:text-5xl">{overallTitle}</h1>
      <p class="mb-6 text-lg text-gray-700">
        You scored <strong>{total}</strong> out of <strong>{maxTotal}</strong>.
      </p>
      {
        data.resultsSubtitle ? (
          <p class="mx-auto max-w-2xl text-base leading-relaxed text-gray-700 md:text-lg">
            {data.resultsSubtitle}
          </p>
        ) : null
      }
    </section>

    {/* TEMPORARY: remove once the mailing-list flow can deliver personalised result reports. */}
    <section class="mx-auto mb-8 max-w-3xl">
      <div
        class="rounded-md border-l-4 border-indigo-500 bg-indigo-50 p-4 text-gray-800"
        role="note"
      >
        <p>
          <strong>A quick note.</strong> This page is your result. Any link you save or revisit will land you right back here. We can't yet send you a personalised report by email, but watch your inbox for a deep dive on these failure modes followed by a short series of related emails.
        </p>
      </div>
    </section>

    <section class="mx-auto max-w-3xl">
      <div
        class="prose prose-blue prose-headings:scroll-mt-24 prose-strong:text-blue-900 max-w-none"
      >
        <Content />
      </div>
    </section>

    <section class="mx-auto mt-12 max-w-3xl text-center">
      <a
        href={`/quiz/${entry.id}/`}
        class="inline-block rounded-md border border-indigo-600 px-5 py-2.5 text-base font-medium text-indigo-700 transition hover:bg-indigo-50"
      >
        Test your knowledge again
      </a>
    </section>
  </div>
</Layout>

import { defineCollection, reference } from 'astro:content';
import { z } from 'astro/zod';
import { glob } from 'astro/loaders';
import { createQuizSchema } from './lib/quiz-engine';

const blog = defineCollection({
  loader: glob({
    pattern: ['**/*.md', '**/*.mdx'],
    base: './src/content/blog',
  }),
  schema: ({ image }) =>
    z.object({
      title: z.string(),
      excerpt: z.string().optional(),
      draft: z.boolean().optional(),
      date: z.string(),
      lastUpdated: z.string().optional(),
      coverImage: image().optional(),
      categories: z.array(reference('categories')).optional(),
    }),
});

const categories = defineCollection({
  loader: glob({ pattern: '**/*.mdx', base: './src/content/categories' }),
  schema: z.object({
    title: z.string(),
    description: z.string().optional(),
  }),
});

const courses = defineCollection({
  loader: glob({ pattern: '**/*.mdx', base: './src/content/courses' }),
  schema: ({ image }) =>
    z.object({
      name: z.string(),
      shortName: z.string(),
      description: z.string(),
      navigationDescription: z.string(),
      navigationImage: image(),
      ctaButton: z
        .object({
          text: z.string(),
          href: z.string(),
        })
        .optional(),
      hero: z.object({
        image: image(),
        imageAltText: z.string(),
        heading: z.string(),
        body: z.string(),
        button: z
          .object({
            text: z.string(),
            href: z.string(),
          })
          .optional(),
      }),
      courseHighlights: z
        .array(
          z.object({
            heading: z.string(),
            body: z.string(),
          })
        )
        .max(3),
      courseBadge: image(),
      whoShouldAttend: z.array(z.string()).optional(),

      workshops: z.object({
        heading: z.string(),
        body: z.string(),
        workshops: z.array(
          z.object({
            date: z.string(),
            location: z.string(),
            url: z.string(),
          })
        ),
      }),

      learningGoals: z.object({
        sectionTitle: z.string().optional(),
        heading: z.string(),
        goals: z.array(
          z.object({
            heading: z.string(),
            body: z.string(),
          })
        ),
      }),
      testimonials: z.object({
        heading: z.string(),
        body: z.string(),
      }),

      faqs: z.object({
        heading: z.string(),
        faqs: z.array(reference('faqs')),
      }),
    }),
});

const testimonials = defineCollection({
  loader: glob({ pattern: '**/*.md', base: './src/content/testimonials' }),
  schema: z.object({
    name: z.string(),
    location: z.string(),
    courseType: reference('courses').optional(),
    priority: z.string().optional(),
  }),
});

const faqs = defineCollection({
  loader: glob({ pattern: '**/*.md', base: './src/content/faqs' }),
  schema: z.object({
    question: z.string(),
  }),
});

const glossary = defineCollection({
  loader: glob({
    pattern: ['**/*.md', '**/*.mdx'],
    base: './src/content/glossary',
  }),
  schema: z.object({
    title: z.string(),
    draft: z.boolean().optional(),
    excerpt: z.string().optional(),
    date: z.string(),
    lastUpdated: z.string().optional(),
    relatedTerms: z.array(reference('glossary')).optional(),
    aliases: z.array(z.string()).optional(),
  }),
});

const pages = defineCollection({
  loader: glob({ pattern: '**/*.mdx', base: './src/content/pages' }),
  schema: z.object({
    title: z.string(),
    description: z.string(),
    draft: z.boolean().optional(),
    includeBreadcrumbs: z.boolean().optional(),
    includeCoursesCTA: z.boolean().optional(),
    noIndex: z.boolean().optional(),
    registerButton: z
      .object({
        href: z.string(),
        label: z.string(),
        description: z.string(),
      })
      .optional(),
  }),
});

const seoPages = defineCollection({
  loader: glob({ pattern: '**/*.mdx', base: './src/content/seoPages' }),
  schema: z.object({
    title: z.string(),
    description: z.string(),
    draft: z.boolean().optional(),
    includeBreadcrumbs: z.boolean().optional(),
    includeCoursesCTA: z.boolean().optional(),
    noIndex: z.boolean().optional(),
    registerButton: z
      .object({
        href: z.string(),
        label: z.string(),
        description: z.string(),
      })
      .optional(),
  }),
});

// The engine schema covers quiz mechanics (questions, scoring, levels). APR's
// landing page wants additional marketing copy fields; extend the engine
// schema here rather than pushing site-specific concerns into the engine.
const quizzes = defineCollection({
  loader: glob({ pattern: '**/*.mdx', base: './src/content/quizzes' }),
  schema: (ctx) =>
    createQuizSchema(ctx).extend({
      heroHeading: z.string().optional(),
      heroBody: z.string().optional(),
      categoriesHeading: z.string().optional(),
      persuasion: z.string().optional(),
      // No cakemailFormUrl: the quiz capture is gated through Turnstile and POSTs
      // to /api/newsletter-signup (see GatedQuizStepper), not browser-direct to a
      // Cakemail form. The engine's built-in cakemailFormUrl path is unused here.
      submissionTags: z.array(z.string()).optional(),
      levelTagPrefix: z.string().optional(),
    }),
});

export const collections = {
  blog,
  testimonials,
  faqs,
  courses,
  glossary,
  pages,
  seoPages,
  categories,
  quizzes,
};

