---
/**
 * Renders the `map-move` result style: a per-answer map (work getting more
 * valuable vs. work slipping away) plus one recommended move. Everything the
 * component prints comes from the quiz's `mapMove` frontmatter and the chosen
 * options' sentences, so the engine stays free of any site-specific wording.
 *
 * The page passes the taker's decoded responses; scoring/selection happens in
 * `computeMapMove`. This component is presentation only.
 */
import { computeMapMove } from '../map-move';
import type { MapMoveEntry, QuizData, QuizResponses } from '../types';

interface Props {
  quiz: QuizData;
  responses: QuizResponses;
}

const { quiz, responses } = Astro.props;
const mm = quiz.mapMove;
const result = computeMapMove(quiz, responses);

const framingLine =
  result.framing && mm?.framing ? mm.framing[result.framing] : undefined;

// Minimal, escaped inline markdown: `[label](url)` links only. Content is
// author-controlled (frontmatter), but escaping first keeps this safe if that
// ever changes.
function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function renderInline(text: string): string {
  return escapeHtml(text).replace(
    /\[([^\]]+)\]\(([^)\s]+)\)/g,
    (_m, label: string, url: string) => {
      const external = /^https?:\/\//i.test(url);
      const attrs = external
        ? ` target="_blank" rel="noopener noreferrer"`
        : '';
      return `<a href="${url}"${attrs} class="text-indigo-700 underline hover:text-indigo-900">${label}</a>`;
    },
  );
}

function paragraphs(text?: string): string[] {
  if (!text) return [];
  return text
    .split(/\n\s*\n/)
    .map((p) => p.trim())
    .filter(Boolean);
}

const sentence = (entry: MapMoveEntry): string =>
  entry.sentence ?? '';
---

<div class="mx-auto max-w-3xl">
  <section class="mb-10 text-center">
    <p class="mb-2 text-sm font-medium uppercase tracking-wide text-indigo-600">
      Your result
    </p>
    {
      framingLine ? (
        <h1 class="text-3xl font-bold text-gray-900 md:text-4xl">
          {framingLine}
        </h1>
      ) : (
        <h1 class="text-3xl font-bold text-gray-900 md:text-4xl">
          {quiz.title}
        </h1>
      )
    }
  </section>

  {
    paragraphs(mm?.opening).length > 0 ? (
      <section class="mb-10">
        {paragraphs(mm?.opening).map((p) => (
          <p
            class="mb-4 text-base leading-relaxed text-gray-700 last:mb-0 md:text-lg"
            set:html={renderInline(p)}
          />
        ))}
      </section>
    ) : null
  }

  {/* The map: two columns, gaining and slipping. */}
  <section class="mb-10 grid grid-cols-1 gap-6 md:grid-cols-2">
    <div class="rounded-lg border border-green-200 bg-green-50 p-6">
      <h2 class="mb-4 text-lg font-semibold text-green-900">
        {mm?.gainingHeading}
      </h2>
      {
        result.gaining.length > 0 ? (
          <ul class="space-y-3">
            {result.gaining.map((entry) => (
              <li
                class="text-base leading-relaxed text-gray-800"
                set:html={renderInline(sentence(entry))}
              />
            ))}
          </ul>
        ) : mm?.gainingEmpty ? (
          <p class="text-base leading-relaxed text-gray-600 italic">
            {mm.gainingEmpty}
          </p>
        ) : null
      }
    </div>

    <div class="rounded-lg border border-orange-200 bg-orange-50 p-6">
      <h2 class="mb-4 text-lg font-semibold text-orange-900">
        {mm?.slippingHeading}
      </h2>
      {
        result.slipping.length > 0 ? (
          <ul class="space-y-3">
            {result.slipping.map((entry) => (
              <li
                class="text-base leading-relaxed text-gray-800"
                set:html={renderInline(sentence(entry))}
              />
            ))}
          </ul>
        ) : mm?.slippingEmpty ? (
          <p class="text-base leading-relaxed text-gray-600 italic">
            {mm.slippingEmpty}
          </p>
        ) : null
      }
    </div>
  </section>

  {/* Context notes: the "d" answers that are constraints, not gaps. */}
  {
    result.context.length > 0 ? (
      <section class="mb-10 rounded-lg border border-gray-200 bg-gray-50 p-6">
        {mm?.contextHeading ? (
          <h2 class="mb-4 text-lg font-semibold text-gray-900">
            {mm.contextHeading}
          </h2>
        ) : null}
        <ul class="space-y-3">
          {result.context.map((entry) => (
            <li
              class="text-base leading-relaxed text-gray-700"
              set:html={renderInline(sentence(entry))}
            />
          ))}
        </ul>
      </section>
    ) : null
  }

  {/* The one move. */}
  <section class="mb-10 rounded-lg border-l-4 border-indigo-500 bg-indigo-50 p-6 md:p-8">
    {
      mm?.moveHeading ? (
        <h2 class="mb-4 text-xl font-semibold text-gray-900">
          {mm.moveHeading}
        </h2>
      ) : null
    }
    {
      result.wellPositioned ? (
        paragraphs(mm?.wellPositioned).map((p) => (
          <p
            class="mb-4 text-base leading-relaxed text-gray-800 last:mb-0 md:text-lg"
            set:html={renderInline(p)}
          />
        ))
      ) : (
        <>
          {result.reclaim?.sentence ? (
            <p
              class="mb-4 text-base leading-relaxed text-gray-800 md:text-lg"
              set:html={renderInline(result.reclaim.sentence)}
            />
          ) : null}
          {result.redirect?.sentence ? (
            <p
              class="mb-4 text-base leading-relaxed text-gray-800 md:text-lg"
              set:html={renderInline(result.redirect.sentence)}
            />
          ) : null}
          {result.otherSlipping.length > 0 ? (
            <p class="mt-4 text-base leading-relaxed text-gray-700">
              {mm?.otherSlippingLead ? (
                <span>{mm.otherSlippingLead} </span>
              ) : null}
              <span
                set:html={result.otherSlipping
                  .map((entry) => renderInline(sentence(entry)))
                  .join(' ')}
              />
            </p>
          ) : null}
        </>
      )
    }
  </section>

  {
    paragraphs(mm?.close).length > 0 ? (
      <section class="mb-10">
        {paragraphs(mm?.close).map((p) => (
          <p
            class="mb-4 text-base leading-relaxed text-gray-700 last:mb-0 md:text-lg"
            set:html={renderInline(p)}
          />
        ))}
      </section>
    ) : null
  }

  {
    mm?.cta ? (
      <section class="rounded-lg border border-indigo-200 bg-white p-6 text-center shadow-sm md:p-8">
        {mm.cta.heading ? (
          <h2 class="mb-3 text-2xl font-semibold text-gray-900">
            {mm.cta.heading}
          </h2>
        ) : null}
        {mm.cta.body ? (
          <p class="mx-auto mb-6 max-w-2xl text-base leading-relaxed text-gray-700 md:text-lg">
            {mm.cta.body}
          </p>
        ) : null}
        <a
          href={mm.cta.buttonHref}
          class="inline-block rounded-md bg-orange-500 px-6 py-3 text-base font-medium text-white shadow-sm transition hover:bg-orange-500/90 focus:ring-2 focus:ring-orange-500 focus:ring-offset-2 focus:outline-none"
        >
          {mm.cta.buttonLabel}
        </a>
      </section>
    ) : null
  }
</div>

