import type { APIRoute } from 'astro';
import { cakemailFormUrlFor } from '@/lib/server/cakemail-forms';

// On-demand (Netlify function), not prerendered: it reads request data and a
// runtime secret. With output: 'static', this opts just this route into SSR.
export const prerender = false;

const TURNSTILE_VERIFY_URL =
  'https://challenges.cloudflare.com/turnstile/v0/siteverify';

// Control fields the browser sends that must NOT be forwarded to Cakemail.
const CONTROL_FIELDS = new Set(['cf-turnstile-response', 'form']);

function json(body: unknown, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json' },
  });
}

/**
 * Turnstile-gated signup proxy. The newsletter / AI signup forms POST here
 * (same-origin) with their fields plus a Cloudflare Turnstile token. We verify
 * the token with Cloudflare's static secret, and only on success forward the
 * submission to the matching Cakemail hosted form (URLs are server-only, so the
 * raw Cakemail endpoints aren't exposed in the client bundle for bots to scrape).
 *
 * No Cakemail credentials are involved: the hosted form accepts anonymous POSTs,
 * so this stays set-and-forget (Turnstile keys don't rotate).
 */
export const POST: APIRoute = async ({ request, clientAddress }) => {
  let form: FormData;
  try {
    form = await request.formData();
  } catch {
    return json({ ok: false, error: 'invalid-request' }, 400);
  }

  const token = form.get('cf-turnstile-response');
  if (typeof token !== 'string' || token.length === 0) {
    return json({ ok: false, error: 'missing-token' }, 400);
  }

  const secret = process.env.TURNSTILE_SECRET_KEY;
  if (!secret) {
    console.error('TURNSTILE_SECRET_KEY is not set; rejecting signup.');
    return json({ ok: false, error: 'server-misconfigured' }, 500);
  }

  // 1. Verify the Turnstile token with Cloudflare.
  const verifyBody = new FormData();
  verifyBody.append('secret', secret);
  verifyBody.append('response', token);
  if (clientAddress) verifyBody.append('remoteip', clientAddress);

  try {
    const verifyRes = await fetch(TURNSTILE_VERIFY_URL, {
      method: 'POST',
      body: verifyBody,
    });
    const verifyData = (await verifyRes.json()) as { success?: boolean };
    if (verifyData.success !== true) {
      return json({ ok: false, error: 'challenge-failed' }, 400);
    }
  } catch (err) {
    console.error('Turnstile verification request failed', err);
    return json({ ok: false, error: 'verify-unavailable' }, 502);
  }

  // 2. Forward every non-control field to the matching Cakemail hosted form.
  const target = form.get('form');
  const cakemailUrl = cakemailFormUrlFor(
    typeof target === 'string' ? target : null
  );

  const forward = new FormData();
  for (const [key, value] of form.entries()) {
    if (CONTROL_FIELDS.has(key)) continue;
    forward.append(key, value);
  }

  try {
    await fetch(cakemailUrl, { method: 'POST', body: forward });
  } catch (err) {
    console.error('Cakemail form forward failed', err);
    return json({ ok: false, error: 'forward-failed' }, 502);
  }

  return json({ ok: true }, 200);
};

