export type MapMoveBucket = 'gaining' | 'mixed' | 'slipping' | 'context';

export interface QuizOption {
  text: string;
  score: number;
  /**
   * map-move classification for this answer. `'context'` marks a real-world
   * constraint that must not be scored as a gap. Ignored by the band style.
   */
  bucket?: MapMoveBucket;
  /** Line shown for this answer in the map (gaining/slipping column or context notes). */
  mapSentence?: string;
  /** Shown when this answer is chosen as the reclaim target of the one move. */
  reclaimSentence?: string;
  /** Shown when this answer is chosen as the redirect target of the one move. */
  redirectSentence?: string;
}

export interface QuizQuestion {
  id: string;
  section: string;
  text: string;
  reveal?: string;
  options: QuizOption[];
}

import type { ImageMetadata } from 'astro';

export interface QuizSection {
  id: string;
  label: string;
  blurb?: string;
  /**
   * Optional image rendered alongside the section card on the landing page.
   * `ImageMetadata` when the frontmatter uses a content-relative path
   * (Astro's `image()` helper resolves and optimizes it), or a plain string
   * for remote URLs and paths served from `public/`.
   */
  image?: string | ImageMetadata;
}

export interface QuizLevelThreshold {
  level: string;
  minScore: number;
  maxScore: number;
  title?: string;
}

/**
 * Selects the results-rendering strategy.
 * - `'band'` (default): total score maps to a level; `<ResultCard>` blocks render.
 * - `'map-move'`: renders a per-answer map plus one recommended move.
 */
export type ResultStyle = 'band' | 'map-move';

/** Copy + selection config consumed by the map-move results renderer. */
export interface MapMoveConfig {
  /** Question ids in priority order; the reclaim move picks the first slipping one. */
  reclaimPriority: string[];
  /** Question ids in priority order; the redirect move picks the first slipping one. */
  redirectPriority: string[];
  opening?: string;
  gainingHeading: string;
  gainingEmpty?: string;
  slippingHeading: string;
  slippingEmpty?: string;
  moveHeading?: string;
  otherSlippingLead?: string;
  contextHeading?: string;
  wellPositioned?: string;
  close?: string;
  framing?: {
    gaining: string;
    mixed: string;
    slipping: string;
  };
  cta?: {
    heading?: string;
    body?: string;
    buttonLabel: string;
    buttonHref: string;
  };
}

export interface QuizData {
  title: string;
  description?: string;
  intro?: string;
  resultsSubtitle?: string;
  resultStyle?: ResultStyle;
  sections: QuizSection[];
  questions: QuizQuestion[];
  sectionLevels?: QuizLevelThreshold[];
  overallLevels?: QuizLevelThreshold[];
  mapMove?: MapMoveConfig;
  /**
   * Controls the order in which questions are presented to the user.
   * - `'none'` (default): preserve the order declared in frontmatter.
   * - `'within-sections'`: keep the section order from frontmatter, but
   *   shuffle the questions within each section. Section labels still
   *   appear in their declared order; only the questions inside each
   *   section are randomized.
   * Scoring is order-independent (keyed by question id), so this only
   * affects presentation.
   */
  randomize?: 'none' | 'within-sections';
}

export type QuizResponses = Record<string, number>;

export interface QuizResult {
  total: number;
  maxTotal: number;
  sectionScores: Record<string, number>;
  sectionLevels: Record<string, string>;
  overallLevel: string;
  overallTitle?: string;
}

/** One classified answer in a map-move result. */
export interface MapMoveEntry {
  questionId: string;
  optionIndex: number;
  bucket: MapMoveBucket;
  /** The map line for this answer (from the chosen option's `mapSentence`). */
  sentence?: string;
}

/** A selected move target plus the copy to render for it. */
export interface MapMoveTarget {
  entry: MapMoveEntry;
  sentence?: string;
}

export interface MapMoveResult {
  gaining: MapMoveEntry[];
  slipping: MapMoveEntry[];
  context: MapMoveEntry[];
  /** Highest-priority slipping answer to reclaim time from, or null if none slips. */
  reclaim: MapMoveTarget | null;
  /** Highest-priority slipping answer to redirect the reclaimed time into. */
  redirect: MapMoveTarget | null;
  /** Slipping answers other than the reclaim/redirect targets. */
  otherSlipping: MapMoveEntry[];
  /** True when nothing is slipping — the "rare case" fallback. */
  wellPositioned: boolean;
  /** Light framing bucket for the descriptive line, or null when no framing copy exists. */
  framing: 'gaining' | 'mixed' | 'slipping' | null;
}

