function QuestionScreen({
  quiz,
  question,
  chosenIndex,
  revealed,
  showCorrectness,
  onPick,
  onNext,
}: {
  quiz: QuizData;
  question: QuizQuestion;
  chosenIndex: number | undefined;
  revealed: boolean;
  showCorrectness: boolean;
  onPick: (optionIndex: number) => void;
  onNext: () => void;
}) {
  const section = quiz.sections.find((s) => s.id === question.section);
  const maxOptionScore = Math.max(...question.options.map((o) => o.score));
  const userGotItRight =
    revealed &&
    chosenIndex !== undefined &&
    question.options[chosenIndex]?.score === maxOptionScore;

  return (
    <div className="rounded-lg border border-gray-200 bg-white p-6 shadow-sm md:p-8">
      {section ? (
        <p className="mb-2 text-sm font-medium uppercase tracking-wide text-indigo-600">
          {section.label}
        </p>
      ) : null}
      <h2 className="mb-6 text-xl font-semibold text-gray-900 md:text-2xl">{question.text}</h2>
      <ul className="space-y-3">
        {question.options.map((option, idx) => {
          const isChosen = chosenIndex === idx;
          const isCorrect = showCorrectness && option.score === maxOptionScore;
          const showAsCorrectPick = revealed && isCorrect && userGotItRight;
          const showAsCorrectAnswer = revealed && isCorrect && !userGotItRight;
          const showAsWrong = revealed && isChosen && !isCorrect;
          let optionClasses =
            'w-full rounded-md px-4 py-3 text-left transition focus:outline-none focus:ring-2 focus:ring-indigo-500';
          if (showAsCorrectPick) {
            // User got it right: filled green box on their (correct) pick.
            optionClasses += ' border-2 border-green-600 bg-green-50';
          } else if (showAsCorrectAnswer) {
            // User got it wrong: outline-only on the correct answer so it
            // reads as a reference, not a celebration.
            optionClasses += ' border-2 border-green-600 bg-white';
          } else if (showAsWrong) {
            optionClasses += ' border-2 border-orange-500 bg-orange-50';
          } else if (isChosen) {
            optionClasses += ' border border-indigo-500 bg-indigo-50';
          } else if (revealed) {
            // Other non-chosen, non-correct options after reveal: mute them.
            optionClasses += ' border border-gray-200 bg-white text-gray-500';
          } else {
            optionClasses += ' border border-gray-300 bg-white hover:border-indigo-400 hover:bg-indigo-50';
          }
          return (
            <li key={idx}>
              <button
                type="button"
                onClick={() => !revealed && onPick(idx)}
                disabled={revealed}
                className={`${optionClasses} flex items-center justify-between gap-3`}
                aria-pressed={isChosen}
              >
                <span className="text-base">{option.text}</span>
                {showAsCorrectPick ? <CorrectIcon /> : showAsWrong ? <WrongIcon /> : null}
              </button>
            </li>
          );
        })}
